<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Character Input</title>
<style>
  body {
    font-family: Arial, sans-serif;
    margin: 20px;
  }
  input, button {
    margin: 10px 0;
  }
</style>
</head>
<body>
<h1>Character Input</h1>
<label for="charCount">Enter number of characters:</label>
<input type="number" id="charCount" min="1" max="100" value="1">
<button onclick="generateString()">Generate String</button>
<p id="output"></p>

<script>
  function generateString() {
    const count = document.getElementById('charCount').value;
    const output = document.getElementById('output');
    output.textContent = 'a'.repeat(count);
  }
</script>
</body>
</html>
